from decimal import Decimal, ROUND_HALF_UP


class Money:
    def __init__(self, amount):
        if isinstance(amount, Money):
            self._cents = amount._cents
        elif isinstance(amount, int):
            self._cents = amount
        else:
            value = Decimal(str(amount))
            self._cents = int((value * 100).quantize(Decimal("1"), rounding=ROUND_HALF_UP))

    @classmethod
    def from_cents(cls, cents):
        money = cls(0)
        money._cents = int(cents)
        return money

    def __add__(self, other):
        return Money.from_cents(self._cents + other._cents)

    def __mul__(self, qty):
        if isinstance(qty, int):
            return Money.from_cents(self._cents * qty)

        value = Decimal(str(qty))
        cents = (Decimal(self._cents) * value).quantize(Decimal("1"), rounding=ROUND_HALF_UP)
        return Money.from_cents(int(cents))

    def __eq__(self, other):
        if isinstance(other, Money):
            return self._cents == other._cents
        return False

    def __repr__(self):
        sign = "-" if self._cents < 0 else ""
        abs_cents = abs(self._cents)
        return f"Money({sign}{abs_cents // 100}.{abs_cents % 100:02d})"

    def cents(self):
        return self._cents

