import os
from urllib.parse import unquote


def safe_join(base, user_path):
    if "\x00" in base:
        raise ValueError("NUL byte in base path")

    decoded = unquote(user_path)

    if "\x00" in decoded:
        raise ValueError("NUL byte in user path")

    normalized = decoded.replace("\\", "/")

    if normalized.startswith("/") or (len(normalized) >= 2 and normalized[1] == ":"):
        raise ValueError("absolute path not allowed")

    base_real = os.path.realpath(base)
    candidate = os.path.join(base_real, normalized)
    candidate_real = os.path.realpath(candidate)

    try:
        if os.path.commonpath([base_real, candidate_real]) != base_real:
            raise ValueError("path escapes base")
    except ValueError:
        raise ValueError("path escapes base")

    return candidate_real

