import sqlite3


def init_v1(conn):
    conn.execute("CREATE TABLE users (id INTEGER PRIMARY KEY, name TEXT, email TEXT)")
    conn.execute("CREATE TABLE schema_version (version INTEGER)")
    conn.execute("INSERT INTO schema_version VALUES (1)")
    conn.commit()


def version(conn):
    return conn.execute("SELECT version FROM schema_version").fetchone()[0]


def migrate(conn):
    try:
        schema_rows = conn.execute("SELECT version FROM schema_version").fetchall()
    except sqlite3.OperationalError:
        conn.execute("CREATE TABLE schema_version (version INTEGER)")
        conn.execute("INSERT INTO schema_version VALUES (2)")
        schema_rows = [(2,)]

    current_version = schema_rows[0][0] if schema_rows else None

    try:
        user_columns = [desc[0] for desc in conn.execute("SELECT * FROM users").description]
    except sqlite3.OperationalError:
        user_columns = []

    has_email_domain = "email_domain" in user_columns

    if current_version != 2 or not has_email_domain:
        if not has_email_domain:
            try:
                conn.execute("ALTER TABLE users ADD COLUMN email_domain TEXT")
            except sqlite3.OperationalError:
                pass

        try:
            users = conn.execute("SELECT id, email FROM users").fetchall()
        except sqlite3.OperationalError:
            users = []

        for user_id, email in users:
            if email is None or "@" not in email:
                continue
            domain = email.rsplit("@", 1)[1].lower()
            conn.execute(
                "UPDATE users SET email_domain = ? WHERE id = ? AND email_domain IS NULL",
                (domain, user_id),
            )

    if not schema_rows:
        conn.execute("INSERT INTO schema_version VALUES (2)")
    elif len(schema_rows) == 1:
        if schema_rows[0][0] != 2:
            conn.execute("UPDATE schema_version SET version = 2")
    else:
        conn.execute("DELETE FROM schema_version")
        conn.execute("INSERT INTO schema_version VALUES (2)")

    conn.commit()

