class Money:
    def __init__(self, amount):
        self._cents = self._to_cents(amount)

    def _to_cents(self, amount):
        if isinstance(amount, Money):
            return amount.cents()

        if isinstance(amount, int):
            return amount * 100

        if isinstance(amount, float):
            amount = str(amount)

        text = str(amount).strip()
        sign = 1
        if text.startswith("-"):
            sign = -1
            text = text[1:]
        elif text.startswith("+"):
            text = text[1:]

        if "." in text:
            whole, frac = text.split(".", 1)
        else:
            whole, frac = text, ""

        whole = int(whole) if whole else 0
        frac = (frac + "00")[:2]
        return sign * (whole * 100 + int(frac))

    def __add__(self, other):
        return Money.from_cents(self.cents() + other.cents())

    def __mul__(self, qty):
        return Money.from_cents(self.cents() * int(qty))

    def __eq__(self, other):
        return self.cents() == other.cents()

    def __repr__(self):
        value = self.cents()
        sign = "-" if value < 0 else ""
        value = abs(value)
        return f"Money({sign}{value // 100}.{value % 100:02d})"

    def cents(self):
        return self._cents

    @classmethod
    def from_cents(cls, cents):
        money = cls(0)
        money._cents = int(cents)
        return money

