import os
import urllib.parse


def safe_join(base, user_path):
    decoded = urllib.parse.unquote(user_path)

    if "\x00" in decoded:
        raise ValueError("NUL byte in path")

    if decoded.startswith(("/", "\\")) or os.path.isabs(decoded):
        raise ValueError("absolute path")

    normalized = decoded.replace("\\", "/")

    base_real = os.path.realpath(base)
    joined = os.path.join(base_real, normalized)
    normalized_path = os.path.normpath(joined)

    if not _is_inside(base_real, normalized_path):
        raise ValueError("path escapes base")

    resolved = os.path.realpath(normalized_path)

    if not _is_inside(base_real, resolved):
        raise ValueError("resolved path escapes base")

    return resolved


def _is_inside(base, path):
    try:
        return os.path.commonpath([base, path]) == base
    except ValueError:
        return False

