def init_v1(conn):
    conn.execute("CREATE TABLE users (id INTEGER PRIMARY KEY, name TEXT, email TEXT)")
    conn.execute("CREATE TABLE schema_version (version INTEGER)")
    conn.execute("INSERT INTO schema_version VALUES (1)")
    conn.commit()


def version(conn):
    return conn.execute("SELECT version FROM schema_version").fetchone()[0]


def migrate(conn):
    def has_email_domain():
        try:
            conn.execute("SELECT email_domain FROM users LIMIT 0")
            return True
        except sqlite3.OperationalError:
            return False

    try:
        schema_rows = conn.execute("SELECT version FROM schema_version").fetchall()
    except sqlite3.OperationalError:
        try:
            conn.execute("CREATE TABLE schema_version (version INTEGER)")
        except sqlite3.OperationalError:
            pass
        schema_rows = []

    if len(schema_rows) == 1 and schema_rows[0][0] == 2 and has_email_domain():
        return

    try:
        conn.execute("ALTER TABLE users ADD COLUMN email_domain TEXT")
    except sqlite3.OperationalError:
        pass

    try:
        rows = conn.execute("SELECT id, email, email_domain FROM users").fetchall()
    except sqlite3.OperationalError:
        rows = []

    for user_id, email, current_domain in rows:
        if current_domain is not None:
            continue

        if email is None:
            continue

        if isinstance(email, bytes):
            email = email.decode("utf-8", "ignore")
        else:
            email = str(email)

        if "@" not in email:
            continue

        domain = email.rsplit("@", 1)[1].lower()

        if user_id is None:
            conn.execute("UPDATE users SET email_domain = ? WHERE id IS NULL", (domain,))
        else:
            conn.execute("UPDATE users SET email_domain = ? WHERE id = ?", (domain, user_id))

    conn.execute("DELETE FROM schema_version")
    conn.execute("INSERT INTO schema_version VALUES (2)")
    conn.commit()

